'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),V=require('./character-vault.js'),G=require('./character-gear.js');
function storage(raw=null,f={}){return {raw,log:[],getItem(k){assert.equal(k,V.KEY);if(f.read)throw Error('denied');return this.raw;},setItem(k,v){assert.equal(k,V.KEY);if(f.write)throw Error('quota');this.log.push([k,v]);this.raw=v;}};}
const build=(id='one',name='Feline')=>V.newBuild(id,name);
test('explicit save only; records persist across reload without startup writes',()=>{const s=storage(),v=V.createVault(()=>s);assert.deepEqual(s.log,[]);assert.ok(v.save(build()).ok);const n=V.createVault(()=>s);assert.deepEqual(n.read(),v.read());assert.equal(s.log.length,1);});
test('damaged, empty, unsupported and unknown-field records remain unchanged across interactions and two reloads',()=>{for(const raw of ['', '{bad','null','[]','42',JSON.stringify({...V.empty(),version:'1'}),JSON.stringify({...V.empty(),version:2}),JSON.stringify({...V.empty(),future:true})]){const s=storage(raw);for(let i=0;i<3;i++){const v=V.createVault(()=>s);assert.equal(v.save(build()).ok,false);assert.equal(v.read().builds.length,1);assert.equal(s.raw,raw);}assert.deepEqual(s.log,[]);}});
test('denied storage getter and read failure retain session editing with zero writes',()=>{const v=V.createVault(()=>{throw Error('getter denied');});assert.equal(v.status(),'unavailable');assert.equal(v.save(build()).ok,false);assert.equal(v.read().builds.length,1);const s=storage('original',{read:true}),x=V.createVault(()=>s);x.save(build());assert.equal(s.raw,'original');assert.deepEqual(s.log,[]);});
test('failed writes retain original bytes and keep session builds exportable',()=>{const s=storage(JSON.stringify(V.empty()),{write:true}),raw=s.raw,v=V.createVault(()=>s);assert.equal(v.save(build()).reason,'write-failed');assert.equal(s.raw,raw);assert.equal(JSON.parse(v.export()).builds.length,1);});
test('name conflicts do not overwrite; reads are detached snapshots',()=>{const s=storage(),v=V.createVault(()=>s);v.save(build());const raw=s.raw;assert.equal(v.save(build('two',' FELINE ')).reason,'name-conflict');assert.equal(s.raw,raw);v.read().builds[0].name='changed';assert.equal(v.read().builds[0].name,'Feline');});
test('designation is explicit and normal saves never change the designated build',()=>{const s=storage(),v=V.createVault(()=>s);v.save(build());assert.equal(v.read().activeId,null);v.designate('one');v.save(build('two','Experiment'));assert.equal(V.createVault(()=>s).read().activeId,'one');assert.equal(v.designate('missing').reason,'not-saved');});
test('external tab changes are detected before any write',()=>{const s=storage(),v=V.createVault(()=>s);s.raw=JSON.stringify({...V.empty(),builds:[build('other','Other')]});const raw=s.raw;assert.equal(v.save(build()).reason,'changed-elsewhere');assert.equal(s.raw,raw);assert.deepEqual(s.log,[]);});
test('invalid schema, duplicate IDs, dangling designation and wrong-slot equipment are rejected',()=>{const b=build();b.equipment.chest='feline-steel-enhanced';assert.equal(V.validBuild(b),false);assert.equal(V.valid({...V.empty(),builds:[build(),build()]}),false);assert.equal(V.valid({...V.empty(),activeId:'missing'}),false);const s=storage(),v=V.createVault(()=>s);assert.equal(v.save(b).reason,'invalid');assert.deepEqual(s.log,[]);});
test('30 sourced Feline identities cover supported slots and tiers without invented stats',()=>{assert.equal(Object.keys(G.items).length,30);for(const x of Object.values(G.items)){const b=build();b.equipment[x.slot]=x.id;assert.ok(V.validBuild(b));assert.equal(x.stats,null);assert.equal(x.level,null);assert.equal(x.content,x.tier==='grandmaster'?'Blood and Wine':'Base Game');assert.ok(x.source.startsWith('https://'));}});
test('entry and assets use candidate cache URLs; UI delegates all persistence',()=>{const fs=require('node:fs');assert.ok(fs.readFileSync('index.html','utf8').includes('character-entry.js?v=character-foundation-v1'));const html=fs.readFileSync('character.html','utf8');for(const f of ['character.css','character-vault.js','character-gear.js','character-ui.js'])assert.ok(html.includes(f+'?v='+(['character-vault.js'].includes(f)?'character-foundation-v1':'character-gear-reference-v1')));assert.ok(!fs.readFileSync('character-ui.js','utf8').includes('localStorage.setItem'));});
